using System.Security.Cryptography;
using System.Text;
using OzFw.ScribanCodeGen.Model;

namespace OzFw.ScribanCodeGen.Sql
{
    /// <param name="Scaffold">
    /// true: yalnızca dosya yoksa oluşturulur, sonra geliştiriciye aittir (csproj, Program.cs, partial iskeletler).
    /// false: her çalıştırmada yeniden üretilir (auto-generated).
    /// </param>
    public sealed record GeneratedFile(string RelativePath, string Content, bool Scaffold = false);

    /// <summary>
    /// Normalize edilmiş modelden PostgreSQL DDL üretir (migration yok; script review edilip elle uygulanır).
    /// - Tablolar FK bağımlılığına göre sıralanır (önce referans verilenler); eşitlikte tablo adı sırası.
    /// - FK'nin hedef tablosu daha önce oluşturulmuşsa (ya da kendine referanssa) constraint CREATE TABLE içinde yazılır;
    ///   döngüdeki FK'ler en sona tekrar çalıştırılabilir DO bloklarıyla ALTER TABLE olarak eklenir.
    /// - Tüm ifadeler idempotenttir (IF NOT EXISTS / duplicate_object); script birden fazla kez çalıştırılabilir.
    /// - Tanımlayıcılar her zaman tırnaklıdır (Npgsql/EF ile birebir aynı adlar).
    /// </summary>
    public static class PostgresDdlGenerator
    {
        private const int MaxIdentifierLength = 63;
        private const string Nl = "\n";

        private sealed record Fk(EntityModel Source, RelationModel Relation, FieldModel Field, EntityModel Target)
        {
            public string Name => ConstraintName("fk", Source.Table!, Field.Column!);
        }

        public static IReadOnlyList<GeneratedFile> Generate(CodeGenModel model)
        {
            var schema = model.DbSchema!;
            var folder = $"sql/{Naming.ToSnake(model.Module)}";
            var ordered = TopologicalOrder(model);

            var created = new HashSet<EntityModel>();
            var sections = new List<(EntityModel Entity, string Body, List<Fk> Deferred)>();
            foreach (var entity in ordered)
            {
                created.Add(entity);
                var fks = ForeignKeys(model, entity).ToList();
                var inline = fks.Where(f => created.Contains(f.Target)).ToList();
                var deferred = fks.Except(inline).ToList();
                sections.Add((entity, TableSection(schema, entity, inline), deferred));
            }

            var allDeferred = sections.SelectMany(s => s.Deferred).ToList();
            var files = new List<GeneratedFile>();

            var all = new StringBuilder();
            all.Append(Header(model, null));
            all.Append(SchemaStatement(schema));
            foreach (var s in sections)
                all.Append(Nl).Append(s.Body);
            if (allDeferred.Count > 0)
            {
                all.Append(Nl).Append("-- Döngüsel bağımlılık nedeniyle tablolardan sonra eklenen FK'ler").Append(Nl);
                foreach (var fk in allDeferred)
                    all.Append(DeferredFk(schema, fk));
            }
            files.Add(new GeneratedFile($"{folder}/_all.sql", all.ToString()));

            foreach (var s in sections)
            {
                var sb = new StringBuilder();
                sb.Append(Header(model, s.Entity));
                sb.Append(SchemaStatement(schema)).Append(Nl);
                sb.Append(s.Body);
                foreach (var fk in s.Deferred)
                    sb.Append(Nl).Append(DeferredFk(schema, fk));
                files.Add(new GeneratedFile($"{folder}/{s.Entity.Table}.sql", sb.ToString()));
            }

            return files;
        }

        private static string Header(CodeGenModel model, EntityModel? entity)
        {
            var sb = new StringBuilder();
            sb.Append("-- <auto-generated>").Append(Nl);
            sb.Append("--   OzFw.ScribanCodeGen tarafından üretildi. Elle düzenlemeyin; modeli değiştirip yeniden üretin.").Append(Nl);
            sb.Append($"--   Modül: {model.Module}, şema: {model.DbSchema}").Append(Nl);
            if (entity != null)
            {
                sb.Append($"--   Entity: {entity.Name}. Referans verdiği tablolar önceden oluşturulmuş olmalı;").Append(Nl);
                sb.Append("--   modülün tamamı için bağımlılık sırasını gözeten _all.sql dosyasını kullanın.").Append(Nl);
            }
            sb.Append("-- </auto-generated>").Append(Nl).Append(Nl);
            return sb.ToString();
        }

        private static string SchemaStatement(string schema) => $"CREATE SCHEMA IF NOT EXISTS {Q(schema)};{Nl}";

        private static string TableSection(string schema, EntityModel entity, List<Fk> inlineFks)
        {
            var table = $"{Q(schema)}.{Q(entity.Table!)}";
            var lines = new List<string>();

            foreach (var b in BaseEntityFields.All)
                lines.Add($"    {Q(b.Column)} {b.SqlType} {(b.Nullable ? "NULL" : "NOT NULL")}{(b.Default != null ? " DEFAULT " + b.Default : "")}");
            foreach (var f in entity.Fields)
                lines.Add($"    {Q(f.Column!)} {TypeMap.ToPostgres(f)} {(f.Nullable ? "NULL" : "NOT NULL")}");

            lines.Add($"    CONSTRAINT {Q(ConstraintName("pk", entity.Table!))} PRIMARY KEY ({Q("id")})");
            foreach (var fk in inlineFks)
                lines.Add($"    CONSTRAINT {Q(fk.Name)} {FkClause(schema, fk)}");

            var sb = new StringBuilder();
            sb.Append($"-- {entity.Name}").Append(Nl);
            sb.Append($"CREATE TABLE IF NOT EXISTS {table} (").Append(Nl);
            sb.Append(string.Join("," + Nl, lines)).Append(Nl);
            sb.Append(");").Append(Nl);

            foreach (var fk in ForeignKeyFields(entity))
                sb.Append($"CREATE INDEX IF NOT EXISTS {Q(ConstraintName("ix", entity.Table!, fk.Column!))} ON {table} ({Q(fk.Column!)});").Append(Nl);

            if (entity.Description != null)
                sb.Append($"COMMENT ON TABLE {table} IS {Literal(entity.Description)};").Append(Nl);
            foreach (var f in entity.Fields.Where(f => f.Description != null))
                sb.Append($"COMMENT ON COLUMN {table}.{Q(f.Column!)} IS {Literal(f.Description!)};").Append(Nl);

            return sb.ToString();
        }

        private static string FkClause(string schema, Fk fk) =>
            $"FOREIGN KEY ({Q(fk.Field.Column!)}) REFERENCES {Q(schema)}.{Q(fk.Target.Table!)} ({Q("id")}) ON DELETE {OnDeleteActions.ToSql(fk.Relation.OnDelete!)}";

        private static string DeferredFk(string schema, Fk fk)
        {
            var sb = new StringBuilder();
            sb.Append("DO $$").Append(Nl);
            sb.Append("BEGIN").Append(Nl);
            sb.Append($"    ALTER TABLE {Q(schema)}.{Q(fk.Source.Table!)} ADD CONSTRAINT {Q(fk.Name)} {FkClause(schema, fk)};").Append(Nl);
            sb.Append("EXCEPTION WHEN duplicate_object THEN NULL;").Append(Nl);
            sb.Append("END $$;").Append(Nl);
            return sb.ToString();
        }

        private static IEnumerable<Fk> ForeignKeys(CodeGenModel model, EntityModel entity) =>
            entity.Relations.Select(r => new Fk(
                entity,
                r,
                entity.Fields.First(f => f.Name == r.FkField),
                model.Entities.First(e => e.Name == r.Target)));

        private static IEnumerable<FieldModel> ForeignKeyFields(EntityModel entity) =>
            entity.Relations.Select(r => entity.Fields.First(f => f.Name == r.FkField));

        /// <summary>Kahn algoritması; kendine referans yok sayılır, döngüdekiler ad sırasıyla sona eklenir.</summary>
        private static List<EntityModel> TopologicalOrder(CodeGenModel model)
        {
            var byName = model.Entities.ToDictionary(e => e.Name);
            var deps = model.Entities.ToDictionary(
                e => e,
                e => e.Relations.Select(r => byName[r.Target]).Where(t => t != e).ToHashSet());

            var result = new List<EntityModel>();
            var remaining = new HashSet<EntityModel>(model.Entities);
            while (remaining.Count > 0)
            {
                var ready = remaining
                    .Where(e => deps[e].All(d => !remaining.Contains(d)))
                    .OrderBy(e => e.Table, StringComparer.Ordinal)
                    .FirstOrDefault()
                    // Döngü: kalanlardan ada göre ilkini al, FK'leri ertelenir
                    ?? remaining.OrderBy(e => e.Table, StringComparer.Ordinal).First();
                result.Add(ready);
                remaining.Remove(ready);
            }
            return result;
        }

        /// <summary>pk_tablo, fk_tablo_kolon, ix_tablo_kolon; 63 karakteri aşarsa kısaltılıp hash eklenir.</summary>
        public static string ConstraintName(string prefix, params string[] parts)
        {
            var name = prefix + "_" + string.Join("_", parts);
            if (Encoding.UTF8.GetByteCount(name) <= MaxIdentifierLength)
                return name;

            var hash = Convert.ToHexString(SHA1.HashData(Encoding.UTF8.GetBytes(name)))[..8].ToLowerInvariant();
            var keep = name;
            while (Encoding.UTF8.GetByteCount(keep) + 9 > MaxIdentifierLength)
                keep = keep[..^1];
            return keep.TrimEnd('_') + "_" + hash;
        }

        private static string Q(string identifier) => "\"" + identifier.Replace("\"", "\"\"") + "\"";

        private static string Literal(string value) => "'" + value.Replace("'", "''") + "'";
    }
}
